// Cross-implementation parity for the Hyperglyph Generator: the same seed must
// produce the same hyperglyph here as it does in desktop GlyphViz, node for
// node and field for field.
//
// The fixture is generated by tools/dump_hyperglyphs.py, which runs the REAL
// desktop `random_recipe` / `generate_nodes` / `assign_color_index` /
// `apply_idle_motion` over CPython's own Mersenne Twister — so what this diffs
// is the whole chain at once: the MT port (pythonRandom.ts), the ORDER of the
// rng calls in randomRecipe, the hsv conversion, Python's half-to-even
// rounding, and the recipe's placement maths.
//
// It is the only thing that makes the Seed field mean anything across the two
// apps, which is the feature the desktop dialog is built around ("uncheck
// Randomize to lock in that exact seed"). Regenerate the JSON only when the
// desktop generator changes.

import { describe, expect, it } from 'vitest'
import { buildHyperglyphNodes, generateHyperglyph, randomRecipe } from './hyperglyph'
import { PythonRandom } from './pythonRandom'
import type { GvNode } from './types'
import fixtureRaw from './fixtures/hyperglyphs.json?raw'

interface FixtureNode {
  id: number
  type: number
  parent_id: number
  branch_level: number
  translate_x: number
  translate_y: number
  translate_z: number
  rotate_x: number
  rotate_y: number
  rotate_z: number
  scale_x: number
  scale_y: number
  scale_z: number
  color_r: number
  color_g: number
  color_b: number
  color_a: number
  geometry: number
  hide: number
  topo: number
  ratio: number
  rotation_mode: number
  color_index: number
  rotate_rate_x: number
  rotate_rate_y: number
  rotate_rate_z: number
}

interface FixtureCase {
  seed: number
  branch_levels: number
  max_nodes: number
  idle_motion: boolean
  start_id: number
  parent_id: number
  base_branch_level: number
  geometry_family: string
  palette_scheme: string
  translucent: boolean
  level_counts: number[]
  nodes: FixtureNode[]
}

const fixture: { cases: FixtureCase[] } = JSON.parse(fixtureRaw)

/** Integers must match exactly; floats to 1e-9 (the dump rounds nothing). */
const FLOAT_TOLERANCE = 9

function checkNode(got: GvNode, want: FixtureNode, where: string): void {
  const exact: Array<[string, number, number]> = [
    ['id', got.id, want.id],
    ['type', got.type, want.type],
    ['parentId', got.parentId, want.parent_id],
    ['branchLevel', got.branchLevel, want.branch_level],
    ['color.r', got.color.r, want.color_r],
    ['color.g', got.color.g, want.color_g],
    ['color.b', got.color.b, want.color_b],
    ['color.a', got.color.a, want.color_a],
    ['geometry', got.geometry, want.geometry],
    ['hide', got.hide, want.hide],
    ['topo', got.topo, want.topo],
    ['rotationMode', got.rotationMode, want.rotation_mode],
    ['colorIndex', got.colorIndex, want.color_index],
  ]
  for (const [field, a, b] of exact) {
    expect(a, `${where} ${field}`).toBe(b)
  }

  const approx: Array<[string, number, number]> = [
    ['translate.x', got.translate.x, want.translate_x],
    ['translate.y', got.translate.y, want.translate_y],
    ['translate.z', got.translate.z, want.translate_z],
    ['rotate.x', got.rotate.x, want.rotate_x],
    ['rotate.y', got.rotate.y, want.rotate_y],
    ['rotate.z', got.rotate.z, want.rotate_z],
    ['scale.x', got.scale.x, want.scale_x],
    ['scale.y', got.scale.y, want.scale_y],
    ['scale.z', got.scale.z, want.scale_z],
    ['ratio', got.ratio, want.ratio],
    ['rotateRate.x', got.rotateRate.x, want.rotate_rate_x],
    ['rotateRate.y', got.rotateRate.y, want.rotate_rate_y],
    ['rotateRate.z', got.rotateRate.z, want.rotate_rate_z],
  ]
  for (const [field, a, b] of approx) {
    expect(a, `${where} ${field}`).toBeCloseTo(b, FLOAT_TOLERANCE)
  }
}

describe('hyperglyph generator parity with desktop GlyphViz', () => {
  it('has a fixture with every case shape covered', () => {
    expect(fixture.cases.length).toBeGreaterThan(6)
    // The translucent branch draws THREE extra randints per design, so a
    // fixture with no translucent case would leave the conditional-draw path —
    // the easiest way to desynchronise a stream — completely untested.
    expect(fixture.cases.some((c) => c.translucent)).toBe(true)
    expect(fixture.cases.some((c) => !c.idle_motion)).toBe(true)
    expect(fixture.cases.some((c) => c.parent_id !== 0)).toBe(true)
  })

  for (const testCase of fixture.cases) {
    const label =
      `seed ${testCase.seed}, ${testCase.branch_levels} level(s), ` +
      `max ${testCase.max_nodes}${testCase.idle_motion ? '' : ', no idle motion'}`

    it(`reproduces ${label}`, () => {
      const { meta } = randomRecipe(
        testCase.branch_levels,
        testCase.max_nodes,
        new PythonRandom(testCase.seed),
      )
      // The design's creative choices are what the info line reports, so they
      // are part of the contract, not internals.
      expect(meta.geometryFamily).toBe(testCase.geometry_family)
      expect(meta.paletteScheme).toBe(testCase.palette_scheme)
      expect(meta.translucent).toBe(testCase.translucent)
      expect(meta.levelCounts).toEqual(testCase.level_counts)

      const design = generateHyperglyph({
        branchLevels: testCase.branch_levels,
        maxNodes: testCase.max_nodes,
        seed: testCase.seed,
        idleMotion: testCase.idle_motion,
      })
      const nodes = buildHyperglyphNodes(design, {
        startId: testCase.start_id,
        parentId: testCase.parent_id,
        baseBranchLevel: testCase.base_branch_level,
      })

      expect(nodes.length).toBe(testCase.nodes.length)
      for (const [i, want] of testCase.nodes.entries()) {
        checkNode(nodes[i], want, `${label} node[${i}]`)
      }
    })
  }
})
